return [
  {
    json: {
      first_name: "Jordan",
      last_name: "Lee",
      email: "jordan@acmegrowth.com",
      company: "Acme Growth",
      job_title: "VP of Revenue Operations",
      budget: 12000,
      employees: 85,
      urgency: "within 30 days",
      decision_authority: "decision maker",
      need: "Automate lead routing, follow-up, CRM updates, and reporting",
      source: "LinkedIn",
      notes: "Requested a discovery call and shared their current process."
    }
  }
];

const source = $json.body && typeof $json.body === 'object'
  ? $json.body
  : $json;

const text = (value) => value === undefined || value === null
  ? ''
  : String(value).trim();

const numberFrom = (value) => {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  const parsed = Number(String(value ?? '').replace(/[^0-9.-]/g, ''));
  return Number.isFinite(parsed) ? parsed : 0;
};

const normalized = {
  first_name: text(source.first_name || source.firstName || source.name?.split(' ')[0]),
  last_name: text(source.last_name || source.lastName || source.name?.split(' ').slice(1).join(' ')),
  email: text(source.email).toLowerCase(),
  phone: text(source.phone),
  company: text(source.company || source.company_name || source.organization),
  job_title: text(source.job_title || source.jobTitle || source.title),
  budget: numberFrom(source.budget || source.estimated_budget || source.monthly_budget),
  employees: numberFrom(source.employees || source.employee_count || source.company_size),
  urgency: text(source.urgency || source.timeline),
  decision_authority: text(source.decision_authority || source.authority || source.role_in_decision),
  need: text(source.need || source.pain_point || source.challenge || source.message),
  source: text(source.source || source.lead_source || 'Unknown'),
  notes: text(source.notes || source.additional_context),
  received_at: new Date().toISOString()
};

normalized.full_name = [normalized.first_name, normalized.last_name]
  .filter(Boolean)
  .join(' ');

normalized.lead_id = text(source.lead_id || source.id)
  || `LEAD-${Date.now()}-${Math.random().toString(36).slice(2, 8).toUpperCase()}`;

return [{ json: normalized }];

const lead = $json;
let score = 0;
const reasons = [];
const nextActions = [];

const urgency = String(lead.urgency || '').toLowerCase();
const authority = String(lead.decision_authority || '').toLowerCase();
const title = String(lead.job_title || '').toLowerCase();
const need = String(lead.need || '').toLowerCase();
const notes = String(lead.notes || '').toLowerCase();

// Budget: 0-30 points
if (lead.budget >= 10000) {
  score += 30;
  reasons.push('Budget is $10,000 or higher');
} else if (lead.budget >= 5000) {
  score += 24;
  reasons.push('Budget is between $5,000 and $9,999');
} else if (lead.budget >= 2500) {
  score += 16;
  reasons.push('Budget is between $2,500 and $4,999');
} else if (lead.budget > 0) {
  score += 7;
  reasons.push('Budget is below $2,500');
} else {
  reasons.push('Budget was not provided');
}

// Urgency: 0-20 points
if (/(immediately|asap|this week|7 days|urgent)/.test(urgency)) {
  score += 20;
  reasons.push('Implementation is urgent');
} else if (/(30 days|this month|2 weeks|3 weeks|4 weeks)/.test(urgency)) {
  score += 16;
  reasons.push('Implementation is planned within 30 days');
} else if (/(60 days|90 days|quarter|1-3 months|2 months|3 months)/.test(urgency)) {
  score += 9;
  reasons.push('Implementation is planned within 90 days');
} else if (urgency) {
  score += 4;
  reasons.push('A timeline was provided');
} else {
  reasons.push('Timeline was not provided');
}

// Company size: 0-15 points
if (lead.employees >= 50) {
  score += 15;
  reasons.push('Company has 50 or more employees');
} else if (lead.employees >= 20) {
  score += 11;
  reasons.push('Company has 20-49 employees');
} else if (lead.employees >= 5) {
  score += 7;
  reasons.push('Company has 5-19 employees');
} else if (lead.employees > 0) {
  score += 3;
  reasons.push('Company has fewer than 5 employees');
} else {
  reasons.push('Company size was not provided');
}

// Authority: 0-15 points
if (/(owner|founder|ceo|president|decision maker|final decision)/.test(authority + ' ' + title)) {
  score += 15;
  reasons.push('Lead appears to be the final decision-maker');
} else if (/(vp|vice president|director|head of|chief|cmo|cro|coo|cto|cio)/.test(authority + ' ' + title)) {
  score += 13;
  reasons.push('Lead appears to have senior buying influence');
} else if (/(manager|recommend|influence|champion)/.test(authority + ' ' + title)) {
  score += 8;
  reasons.push('Lead appears to influence the purchase');
} else {
  reasons.push('Decision authority is unclear');
}

// Need and fit: 0-15 points
const highFitTerms = [
  'automation', 'lead routing', 'follow-up', 'crm', 'reporting',
  'manual process', 'integration', 'workflow', 'n8n', 'ai'
];
const fitMatches = highFitTerms.filter(term => need.includes(term) || notes.includes(term));

if (fitMatches.length >= 3) {
  score += 15;
  reasons.push(`Strong automation fit: ${fitMatches.slice(0, 4).join(', ')}`);
} else if (fitMatches.length >= 1) {
  score += 10;
  reasons.push(`Relevant automation need: ${fitMatches.join(', ')}`);
} else if (need.length >= 25) {
  score += 5;
  reasons.push('A meaningful business need was described');
} else {
  reasons.push('Business need requires clarification');
}

// Engagement/data quality: 0-5 points
let engagement = 0;
if (lead.email) engagement += 1;
if (lead.phone) engagement += 1;
if (lead.company) engagement += 1;
if (lead.need.length >= 40) engagement += 1;
if (/(call|meeting|demo|proposal|quote)/.test(notes)) engagement += 1;
score += engagement;

score = Math.max(0, Math.min(100, score));

let qualification;
let priority;
let recommendedResponseTime;

if (score >= 80) {
  qualification = 'HOT';
  priority = 'P1';
  recommendedResponseTime = 'Within 15 minutes';
  nextActions.push(
    'Send an immediate personalized acknowledgement',
    'Create or update the CRM opportunity',
    'Assign the lead to a sales owner',
    'Book a discovery call within 24 hours'
  );
} else if (score >= 55) {
  qualification = 'WARM';
  priority = 'P2';
  recommendedResponseTime = 'Within 4 business hours';
  nextActions.push(
    'Send a personalized follow-up',
    'Request missing budget, timeline, or authority details',
    'Add the lead to a short nurture sequence',
    'Offer a discovery call'
  );
} else {
  qualification = 'COLD';
  priority = 'P3';
  recommendedResponseTime = 'Within 1 business day';
  nextActions.push(
    'Send a helpful resource',
    'Add the lead to long-term nurture',
    'Requalify when engagement or buying intent increases'
  );
}

const summary = `${lead.full_name || 'The lead'} from ${lead.company || 'an unspecified company'} scored ${score}/100 and is classified as ${qualification}.`;

return [{
  json: {
    ...lead,
    lead_score: score,
    qualification,
    priority,
    recommended_response_time: recommendedResponseTime,
    qualification_summary: summary,
    scoring_reasons: reasons,
    recommended_next_actions: nextActions,
    qualified_at: new Date().toISOString()
  }
}];

return items.map(item => ({
  json: {
    ...item.json,
    route: 'HOT_LEAD_FAST_TRACK',
    sales_message: `High-priority lead: ${item.json.full_name || item.json.email || item.json.lead_id} scored ${item.json.lead_score}/100. Contact within 15 minutes.`,
    workflow_status: 'Qualified and routed to immediate sales follow-up'
  }
}));

return items.map(item => ({
  json: {
    ...item.json,
    route: 'WARM_LEAD_NURTURE',
    sales_message: `Promising lead: ${item.json.full_name || item.json.email || item.json.lead_id} scored ${item.json.lead_score}/100. Follow up within 4 business hours.`,
    workflow_status: 'Qualified and routed to personalized nurture'
  }
}));

return items.map(item => ({
  json: {
    ...item.json,
    route: 'COLD_LEAD_LONG_TERM_NURTURE',
    sales_message: `Early-stage lead: ${item.json.full_name || item.json.email || item.json.lead_id} scored ${item.json.lead_score}/100. Add to long-term nurture.`,
    workflow_status: 'Qualified and routed to long-term nurture'
  }
}));
